export function getQuestionnaireStats() {
  const allVariants = questionnaireConfig.segmentation_patients.flatMap(p => p.variants);
  return {
    totalSegmentationCases: allVariants.length,
    totalQuestions: allVariants.reduce((acc, v) => acc + v.questions.length, 0),
  };
}
